import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Img } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type ProductShineSweepProps = Record<string, any>;

const ProductShineSweep: React.FC<ProductShineSweepProps> = ({
  backgroundColor = "#f4f4f5",
  transparentBackground = false,
  durationInSeconds = 5,
  productImage = "https://malloy.blob.core.windows.net/web/template_assets/images/product_image.png",
  titleText = "Malloy Studio",
  subtitleText = "Premium Collection",
  textColor = "#18181b",
  shineColor = "rgba(255, 255, 255, 0.9)",
  shineSweepDurationFrames = 45,
  shineAngleDegrees = -35,
  shineRepeatDelayFrames = 60,
}) => {

  {/* Load Google Fonts */ }
  useFontLoader(["Playfair Display"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Canvas-aware sizing
  const minDimension = Math.min(width, height);
  const productSize = minDimension * 0.6;
  const layoutGap = height * 0.04;

  // Entrance Animations
  const productEntranceScale = spring({
    fps,
    frame: frame - 5,
    config: { damping: 14, mass: 0.8 },
  });

  const continuousScale = interpolate(
    frame,
    [0, fps * durationInSeconds],
    [1, 1.05],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  const finalProductScale = productEntranceScale * continuousScale;

  const textOpacity = interpolate(
    frame,
    [15, 30],
    [0, 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  const textTranslateY = interpolate(
    frame,
    [15, 30],
    [20, 0],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  // Shine Sweep Logic
  const shineStartFrame = 25;
  const cycleDuration = shineSweepDurationFrames + shineRepeatDelayFrames;
  
  // Ensure we don't calculate negative modulo
  const activeFrame = Math.max(0, frame - shineStartFrame);
  const cycleFrame = activeFrame % cycleDuration;

  const sweepProgress = interpolate(
    cycleFrame,
    [0, shineSweepDurationFrames],
    [-2, 2], // Move from -200% to 200% to ensure full clearance despite skew
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  const isSweeping = cycleFrame <= shineSweepDurationFrames && frame >= shineStartFrame;
  const shineOpacity = isSweeping ? 1 : 0;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
          width: "100%",
          height: "100%",
          gap: `${layoutGap}px`,
          transition: "none",
        }}
      >
        {/* Title */}
        <div
          style={{
            opacity: textOpacity,
            transform: `translateY(${textTranslateY}px)`,
            transition: "none",
            marginTop: `${height * 0.1}px` // Safe zone adjustment
          }}
        >
          <h1
            style={{
              fontFamily: "Playfair Display",
              fontWeight: 700,
              fontSize: `${minDimension * 0.08}px`,
              color: textColor,
              margin: 0,
              textAlign: "center",
              letterSpacing: "-0.02em",
              transition: "none",
            }}
          >
            {titleText}
          </h1>
        </div>

        {/* Product Container */}
        <div
          style={{
            position: "relative",
            width: `${productSize}px`,
            height: `${productSize}px`,
            transform: `scale(${finalProductScale})`,
            transition: "none",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
          }}
        >
          {/* Base Product Image */}
          <Img
            src={productImage}
            style={{
              width: "100%",
              height: "100%",
              objectFit: "contain",
              transition: "none",
            }}
          />

          {/* Shine Mask Overlay */}
          <div
            style={{
              position: "absolute",
              inset: 0,
              WebkitMaskImage: `url(${productImage})`,
              WebkitMaskSize: "contain",
              WebkitMaskRepeat: "no-repeat",
              WebkitMaskPosition: "center",
              maskImage: `url(${productImage})`,
              maskSize: "contain",
              maskRepeat: "no-repeat",
              maskPosition: "center",
              pointerEvents: "none",
              overflow: "hidden",
              transition: "none",
            }}
          >
            {/* The Moving Shine Gradient */}
            <div
              style={{
                position: "absolute",
                top: "-50%",
                left: 0,
                width: "100%",
                height: "200%", // Oversize to cover corners when skewed
                background: `linear-gradient(to right, transparent 0%, ${shineColor} 50%, transparent 100%)`,
                transform: `translateX(${sweepProgress * 100}%) skewX(${shineAngleDegrees}deg)`,
                opacity: shineOpacity,
                transition: "none",
              }}
            />
          </div>
        </div>

        {/* Subtitle */}
        <div
          style={{
            opacity: textOpacity,
            transform: `translateY(${textTranslateY}px)`,
            transition: "none",
            marginBottom: `${height * 0.1}px` // Safe zone adjustment
          }}
        >
          <p
            style={{
              fontFamily: "Playfair Display",
              fontWeight: 400,
              fontSize: `${minDimension * 0.04}px`,
              color: textColor,
              margin: 0,
              opacity: 0.7,
              textAlign: "center",
              transition: "none",
            }}
          >
            {subtitleText}
          </p>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ProductShineSweep;